import fs from 'fs';
import http from 'http';
import path from 'path';
import chokidar from 'chokidar';
import { WebSocket, WebSocketServer } from 'ws';
import {
  build,
  DEFAULT_CONTENT_DIR,
  DEFAULT_OUTPUT_DIR,
  DEFAULT_TEMPLATES_DIR,
} from './ssg';

/** Default port for the development server. */
export const DEFAULT_PORT = 3000;

/** Id attribute on the injected live-reload script tag. */
export const LIVE_RELOAD_SCRIPT_ID = 'ssg-live-reload';

/** WebSocket endpoint that served pages connect to. */
export const WS_PATH = '/live-reload';

export interface ServeOptions {
  content: string;
  output: string;
  templates: string;
  port: number;
}

export interface DevServer {
  /** Underlying HTTP server. */
  server: http.Server;
  /** WebSocket server attached to the HTTP server. */
  wss: WebSocketServer;
  /** chokidar watcher over content/ and templates/. */
  watcher: chokidar.FSWatcher;
  /** Resolves once the initial file scan has completed. */
  ready: Promise<void>;
  /** Number of rebuilds performed so far. */
  getRebuildCount(): number;
  /** Start listening and resolve with the actual port in use. */
  listen(): Promise<number>;
  /** Close the watcher, WebSocket server, and HTTP server. */
  stop(): Promise<void>;
}

const MIME_TYPES: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.htm': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.ico': 'image/x-icon',
  '.webp': 'image/webp',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
  '.ttf': 'font/ttf',
  '.eot': 'application/vnd.ms-fontobject',
  '.txt': 'text/plain; charset=utf-8',
  '.xml': 'text/xml; charset=utf-8',
  '.map': 'application/json; charset=utf-8',
};

/**
 * The client-side script injected into served HTML pages. It opens a
 * WebSocket connection to the dev server and reloads the page whenever a
 * rebuild has finished.
 */
export function liveReloadScript(port: number): string {
  return `<script id="${LIVE_RELOAD_SCRIPT_ID}">
(function () {
  var port = ${port};
  function connect() {
    var proto = location.protocol === 'https:' ? 'wss:' : 'ws:';
    var ws = new WebSocket(proto + '//' + location.hostname + ':' + port + '${WS_PATH}');
    ws.onmessage = function () { location.reload(); };
    ws.onclose = function () { setTimeout(connect, 1000); };
    ws.onerror = function () { ws.close(); };
  }
  connect();
})();
</script>`;
}

/**
 * Inject the live-reload script into an HTML document, just before the closing
 * `</body>` tag when present, otherwise appended at the end.
 */
export function injectLiveReload(html: string, port: number): string {
  const script = liveReloadScript(port);
  if (/<\/body>/i.test(html)) {
    return html.replace(/<\/body>/i, `${script}\n</body>`);
  }
  return `${html}\n${script}`;
}

/** Send a reload message to every connected client, returning how many got it. */
export function broadcastReload(wss: WebSocketServer): number {
  let count = 0;
  for (const client of wss.clients) {
    if (client.readyState === WebSocket.OPEN) {
      client.send('reload');
      count += 1;
    }
  }
  return count;
}

/** Resolve a request path to an absolute file inside the output directory. */
export function resolveFilePath(url: string | undefined, outputDir: string): string | null {
  const pathname = decodeURIComponent(new URL(url ?? '/', 'http://localhost').pathname);
  let relPath = pathname === '/' ? '/index.html' : pathname;
  if (relPath.endsWith('/')) relPath += 'index.html';

  const root = path.resolve(outputDir);
  const filePath = path.normalize(path.join(root, relPath));
  if (filePath !== root && !filePath.startsWith(root + path.sep)) {
    return null;
  }
  return filePath;
}

function serveFile(req: http.IncomingMessage, res: http.ServerResponse, options: ServeOptions, port: number): void {
  const filePath = resolveFilePath(req.url, options.output);
  if (filePath === null) {
    res.writeHead(403, { 'Content-Type': 'text/plain' });
    res.end('Forbidden');
    return;
  }

  if (!fs.existsSync(filePath) || !fs.statSync(filePath).isFile()) {
    res.writeHead(404, { 'Content-Type': 'text/plain' });
    res.end('Not Found');
    return;
  }

  const ext = path.extname(filePath).toLowerCase();
  const contentType = MIME_TYPES[ext] ?? 'application/octet-stream';
  res.writeHead(200, { 'Content-Type': contentType });

  if (ext === '.html' || ext === '.htm') {
    const html = fs.readFileSync(filePath, 'utf8');
    res.end(injectLiveReload(html, port));
  } else {
    fs.createReadStream(filePath).pipe(res);
  }
}

/**
 * Build the site and start serving it from the output directory with
 * live-reload enabled. Content/ and templates/ are watched and any change
 * triggers a rebuild followed by a reload broadcast to connected browsers.
 */
export function createDevServer(options: ServeOptions): DevServer {
  build(options.content, options.output, options.templates);

  const wss = new WebSocketServer({ noServer: true });
  const outputDir = path.resolve(options.output);
  let actualPort = options.port;

  const server = http.createServer((req, res) => {
    serveFile(req, res, options, actualPort);
  });

  server.on('upgrade', (req, socket, head) => {
    const pathname = new URL(req.url ?? '/', 'http://localhost').pathname;
    if (pathname === WS_PATH) {
      wss.handleUpgrade(req, socket, head, (ws) => {
        wss.emit('connection', ws, req);
      });
    } else {
      socket.destroy();
    }
  });

  const watcher = chokidar.watch([options.content, options.templates], {
    ignoreInitial: true,
    ignored: (watchedPath: string) => {
      const abs = path.resolve(watchedPath);
      return abs === outputDir || abs.startsWith(outputDir + path.sep);
    },
  });

  const ready = new Promise<void>((resolve) => {
    watcher.once('ready', () => resolve());
  });

  let rebuilding = false;
  let pending = false;
  let rebuildCount = 0;

  const rebuild = (): void => {
    if (rebuilding) {
      pending = true;
      return;
    }
    rebuilding = true;
    try {
      build(options.content, options.output, options.templates);
      rebuildCount += 1;
      broadcastReload(wss);
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      broadcastReload(wss);
      broadcast(wss, `error:${message}`);
    } finally {
      rebuilding = false;
      if (pending) {
        pending = false;
        rebuild();
      }
    }
  };

  watcher.on('all', rebuild);

  return {
    server,
    wss,
    watcher,
    ready,
    getRebuildCount: () => rebuildCount,
    listen: () =>
      new Promise<number>((resolve) => {
        server.listen(options.port, () => {
          const addr = server.address();
          actualPort = typeof addr === 'object' && addr !== null ? addr.port : options.port;
          resolve(actualPort);
        });
      }),
    stop: async () => {
      await watcher.close();
      for (const client of wss.clients) client.terminate();
      await new Promise<void>((resolve) => wss.close(() => resolve()));
      await new Promise<void>((resolve) => server.close(() => resolve()));
    },
  };
}

function broadcast(wss: WebSocketServer, message: string): number {
  let count = 0;
  for (const client of wss.clients) {
    if (client.readyState === WebSocket.OPEN) {
      client.send(message);
      count += 1;
    }
  }
  return count;
}

/**
 * Start the dev server and keep the process alive. Resolves once the HTTP
 * server has closed.
 */
export async function startServe(options: ServeOptions): Promise<void> {
  const dev = createDevServer(options);
  const port = await dev.listen();
  process.stdout.write(
    `SSG dev server running at http://localhost:${port}\n` +
      `Watching ${options.content} and ${options.templates}\n`
  );
  await new Promise<void>((resolve) => {
    dev.server.once('close', () => resolve());
  });
}

/** Build default serve options from the conventional directory layout. */
export function defaultServeOptions(port: number = DEFAULT_PORT): ServeOptions {
  return {
    content: DEFAULT_CONTENT_DIR,
    output: DEFAULT_OUTPUT_DIR,
    templates: DEFAULT_TEMPLATES_DIR,
    port,
  };
}

#!/usr/bin/env node

import { build, DEFAULT_CONTENT_DIR, DEFAULT_OUTPUT_DIR, DEFAULT_TEMPLATES_DIR } from './ssg';
import { DEFAULT_PORT, ServeOptions, startServe } from './serve';

export interface CliOptions {
  command: string;
  content: string;
  output: string;
  templates: string;
  port: number;
}

/**
 * Parse CLI arguments for the `ssg` binary.
 * Usage: ssg build [--content <dir>] [--output <dir>] [--templates <dir>]
 *        ssg serve [--content <dir>] [--output <dir>] [--templates <dir>] [--port <port>]
 */
export function parseArgs(argv: string[]): CliOptions {
  if (argv.includes('--help') || argv.includes('-h')) {
    throw new HelpError();
  }

  const options: CliOptions = {
    command: argv[0] ?? '',
    content: DEFAULT_CONTENT_DIR,
    output: DEFAULT_OUTPUT_DIR,
    templates: DEFAULT_TEMPLATES_DIR,
    port: DEFAULT_PORT,
  };

  const flags = argv.slice(1);
  for (let i = 0; i < flags.length; i++) {
    const flag = flags[i];
    if (flag === '--content' || flag === '--output' || flag === '--templates' || flag === '--port') {
      const value = flags[i + 1];
      if (value === undefined) {
        throw new Error(`Missing value for ${flag}`);
      }
      if (flag === '--content') {
        options.content = value;
      } else if (flag === '--output') {
        options.output = value;
      } else if (flag === '--templates') {
        options.templates = value;
      } else {
        const parsedPort = Number(value);
        if (!Number.isInteger(parsedPort) || parsedPort < 0 || parsedPort > 65535) {
          throw new Error(`Invalid port: ${value}`);
        }
        options.port = parsedPort;
      }
      i++;
    } else {
      throw new Error(`Unknown option: ${flag}`);
    }
  }

  return options;
}

export class HelpError extends Error {
  constructor() {
    super('help requested');
    this.name = 'HelpError';
  }
}

export const USAGE = `Usage: ssg build [--content <dir>] [--output <dir>] [--templates <dir>]
       ssg serve [--content <dir>] [--output <dir>] [--templates <dir>] [--port <port>]

Build a static site from Markdown files, or run a live-reload dev server.

Commands:
  build                   Generate the static site once
  serve                   Start a dev server with live reload

Options:
  --content <dir>     Directory containing Markdown sources (default: ${DEFAULT_CONTENT_DIR})
  --output <dir>      Directory where the generated site is written (default: ${DEFAULT_OUTPUT_DIR})
  --templates <dir>   Directory containing templates, layouts, and partials (default: ${DEFAULT_TEMPLATES_DIR})
  --port <port>       Port for the dev server (default: ${DEFAULT_PORT})
  -h, --help          Show this help message
`;

/** Build serve options from parsed CLI options. */
export function toServeOptions(options: CliOptions): ServeOptions {
  return {
    content: options.content,
    output: options.output,
    templates: options.templates,
    port: options.port,
  };
}

/**
 * Run the CLI with a given argument list and return a human-readable summary.
 * Exported separately from `main` so it can be exercised in tests.
 */
export function run(argv: string[]): string {
  let options: CliOptions;
  try {
    options = parseArgs(argv);
  } catch (err) {
    if (err instanceof HelpError) {
      return USAGE;
    }
    throw err;
  }

  if (options.command !== 'build') {
    throw new Error(`Unknown command: ${options.command}\n\n${USAGE}`);
  }

  const pages = build(options.content, options.output, options.templates);
  return `Built ${pages.length} page(s) into ${options.output}`;
}

function serveCommand(args: string[]): void {
  let options: CliOptions;
  try {
    options = parseArgs(['serve', ...args]);
  } catch (err) {
    process.stderr.write((err instanceof Error ? err.message : String(err)) + '\n');
    process.exitCode = 1;
    return;
  }
  startServe(toServeOptions(options)).catch((err) => {
    process.stderr.write((err instanceof Error ? err.message : String(err)) + '\n');
    process.exitCode = 1;
  });
}

function main(): void {
  const argv = process.argv.slice(2);
  if (argv[0] === 'serve') {
    serveCommand(argv.slice(1));
    return;
  }
  try {
    const message = run(argv);
    process.stdout.write(message + '\n');
  } catch (err) {
    process.stderr.write(
      (err instanceof Error ? err.message : String(err)) + '\n'
    );
    process.exitCode = 1;
  }
}

if (require.main === module) {
  main();
}

import fs from 'fs';
import http from 'http';
import os from 'os';
import path from 'path';
import { WebSocket } from 'ws';
import { parseArgs, toServeOptions, USAGE } from '../src/cli';
import {
  DEFAULT_PORT,
  LIVE_RELOAD_SCRIPT_ID,
  WS_PATH,
  broadcastReload,
  createDevServer,
  injectLiveReload,
  liveReloadScript,
  resolveFilePath,
} from '../src/serve';

function makeTempDir(): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-serve-'));
}

function get(url: string): Promise<{ status: number; body: string }> {
  return new Promise((resolve, reject) => {
    http
      .get(url, (res) => {
        let body = '';
        res.setEncoding('utf8');
        res.on('data', (chunk) => (body += chunk));
        res.on('end', () => resolve({ status: res.statusCode ?? 0, body }));
      })
      .on('error', reject);
  });
}

async function waitFor(cond: () => boolean, timeout = 8000): Promise<void> {
  const start = Date.now();
  while (!cond()) {
    if (Date.now() - start > timeout) {
      throw new Error('timed out waiting for condition');
    }
    await new Promise((r) => setTimeout(r, 20));
  }
}

describe('parseArgs with serve', () => {
  it('uses the default port when none is given', () => {
    const options = parseArgs(['serve']);
    expect(options.command).toBe('serve');
    expect(options.port).toBe(DEFAULT_PORT);
  });

  it('parses the --port option', () => {
    const options = parseArgs(['serve', '--port', '5000']);
    expect(options.command).toBe('serve');
    expect(options.port).toBe(5000);
  });

  it('parses --port alongside directory options', () => {
    const options = parseArgs(['serve', '--content', 'pages', '--output', 'public', '--port', '8080']);
    expect(options.content).toBe('pages');
    expect(options.output).toBe('public');
    expect(options.port).toBe(8080);
  });

  it('throws on a non-numeric port', () => {
    expect(() => parseArgs(['serve', '--port', 'abc'])).toThrow(/Invalid port/);
  });

  it('documents the serve command in the usage text', () => {
    expect(USAGE).toContain('ssg serve');
    expect(USAGE).toContain('--port <port>');
  });

  it('converts CLI options into serve options', () => {
    const options = parseArgs(['serve', '--port', '4000']);
    const serve = toServeOptions(options);
    expect(serve.port).toBe(4000);
    expect(serve.output).toBe('./dist');
  });
});

describe('live reload script injection', () => {
  it('injects a WebSocket script before the closing body tag', () => {
    const html = '<!DOCTYPE html><html><body><h1>Hi</h1></body></html>';
    const out = injectLiveReload(html, 3000);
    expect(out).toContain(LIVE_RELOAD_SCRIPT_ID);
    expect(out).toContain('ws://');
    expect(out).toContain(':3000' + WS_PATH);
    expect(out).toContain('<h1>Hi</h1>');
    expect(out.indexOf(LIVE_RELOAD_SCRIPT_ID)).toBeLessThan(out.indexOf('</body>'));
  });

  it('appends the script when there is no body tag', () => {
    const out = injectLiveReload('<p>bare</p>', 4000);
    expect(out).toContain(LIVE_RELOAD_SCRIPT_ID);
    expect(out).toContain(':4000' + WS_PATH);
  });

  it('builds a reload script for the requested port', () => {
    const script = liveReloadScript(1234);
    expect(script).toContain(':1234' + WS_PATH);
    expect(script).toContain('location.reload');
  });
});

describe('resolveFilePath', () => {
  it('maps / to index.html', () => {
    const dir = makeTempDir();
    expect(resolveFilePath('/', dir)).toBe(path.join(dir, 'index.html'));
  });

  it('maps /about.html to about.html', () => {
    const dir = makeTempDir();
    expect(resolveFilePath('/about.html', dir)).toBe(path.join(dir, 'about.html'));
  });

  it('blocks path traversal outside the output directory', () => {
    const dir = makeTempDir();
    expect(resolveFilePath('/../../etc/passwd', dir)).toBeNull();
  });
});

describe('dev server', () => {
  it('serves built pages with live-reload injected', async () => {
    const content = makeTempDir();
    const output = makeTempDir();
    const templates = makeTempDir();
    try {
      fs.writeFileSync(path.join(content, 'post.md'), '<!--\ntitle: Post\n-->\n# Post body');

      const dev = createDevServer({ content, output, templates, port: 0 });
      const port = await dev.listen();
      try {
        const res = await get(`http://127.0.0.1:${port}/post.html`);
        expect(res.status).toBe(200);
        expect(res.body).toContain('<title>Post</title>');
        expect(res.body).toContain('<h1>Post body</h1>');
        expect(res.body).toContain(LIVE_RELOAD_SCRIPT_ID);

        const index = await get(`http://127.0.0.1:${port}/`);
        expect(index.status).toBe(200);
        expect(index.body).toContain('<a href="post.html">Post</a>');
        expect(index.body).toContain(LIVE_RELOAD_SCRIPT_ID);
      } finally {
        await dev.stop();
      }
    } finally {
      fs.rmSync(content, { recursive: true, force: true });
      fs.rmSync(output, { recursive: true, force: true });
      fs.rmSync(templates, { recursive: true, force: true });
    }
  });

  it('returns 404 for missing pages', async () => {
    const content = makeTempDir();
    const output = makeTempDir();
    const templates = makeTempDir();
    try {
      fs.writeFileSync(path.join(content, 'a.md'), '<!--\ntitle: A\n-->\n# A');
      const dev = createDevServer({ content, output, templates, port: 0 });
      const port = await dev.listen();
      try {
        const res = await get(`http://127.0.0.1:${port}/nope.html`);
        expect(res.status).toBe(404);
      } finally {
        await dev.stop();
      }
    } finally {
      fs.rmSync(content, { recursive: true, force: true });
      fs.rmSync(output, { recursive: true, force: true });
      fs.rmSync(templates, { recursive: true, force: true });
    }
  });

  it('rebuilds the site and broadcasts a reload when content changes', async () => {
    const content = makeTempDir();
    const output = makeTempDir();
    const templates = makeTempDir();
    try {
      fs.writeFileSync(path.join(content, 'a.md'), '<!--\ntitle: A\n-->\n# A');
      const dev = createDevServer({ content, output, templates, port: 0 });
      const port = await dev.listen();
      await dev.ready;

      const ws = new WebSocket(`ws://127.0.0.1:${port}${WS_PATH}`);
      await new Promise<void>((resolve, reject) => {
        ws.once('open', () => resolve());
        ws.once('error', reject);
      });
      const messages: string[] = [];
      ws.on('message', (data) => messages.push(String(data)));

      fs.writeFileSync(path.join(content, 'a.md'), '<!--\ntitle: A2\n-->\n# A2');
      await waitFor(() => messages.includes('reload'));

      expect(messages).toContain('reload');
      expect(dev.getRebuildCount()).toBeGreaterThanOrEqual(1);
      const html = fs.readFileSync(path.join(output, 'a.html'), 'utf8');
      expect(html).toContain('<title>A2</title>');
      expect(html).toContain('<h1>A2</h1>');
      expect(html).not.toContain('<h1>A</h1>');

      ws.close();
      await dev.stop();
    } finally {
      fs.rmSync(content, { recursive: true, force: true });
      fs.rmSync(output, { recursive: true, force: true });
      fs.rmSync(templates, { recursive: true, force: true });
    }
  });

  it('rebuilds when a template file changes', async () => {
    const content = makeTempDir();
    const output = makeTempDir();
    const templates = makeTempDir();
    try {
      fs.writeFileSync(path.join(templates, 'default.hbs'), 'OLD {{title}}');
      fs.writeFileSync(path.join(content, 'a.md'), '<!--\ntitle: A\n-->\n# A');
      const dev = createDevServer({ content, output, templates, port: 0 });
      await dev.listen();
      await dev.ready;

      fs.writeFileSync(path.join(templates, 'default.hbs'), 'NEW {{title}}');
      await waitFor(() => {
        try {
          return fs.readFileSync(path.join(output, 'a.html'), 'utf8').includes('NEW A');
        } catch {
          return false;
        }
      });

      expect(fs.readFileSync(path.join(output, 'a.html'), 'utf8')).toContain('NEW A');
