    } else if (h.constructor && h.constructor.name === 'Timer') {
      extra = 'timeout=' + (h._repeat ? 'repeat' : 'once');
    }
    console.log(' ', name, extra);
  }
}

async function main() {
  const content = fs.mkdtempSync(path.join(os.tmpdir(), 'r-'));
  const output = fs.mkdtempSync(path.join(os.tmpdir(), 'r-'));
  const templates = fs.mkdtempSync(path.join(os.tmpdir(), 'r-'));
  fs.writeFileSync(path.join(content, 'a.md'), '<!--\ntitle: A\n-->\n# A');
  const dev = createDevServer({ content, output, templates, port: 0 });
  const port = await dev.listen();
  await new Promise((res, rej) => http.get(`http://127.0.0.1:${port}/a.html`, { agent: false }, (r) => {
    let b = ''; r.on('data', (c) => b += c); r.on('end', () => { console.log('got', r.statusCode); res(); });
  }).on('error', rej));
  const ws = new WebSocket(`ws://127.0.0.1:${port}${WS_PATH}`);
  await new Promise((res, rej) => { ws.once('open', res); ws.once('error', rej); });
  fs.writeFileSync(path.join(content, 'a.md'), '<!--\ntitle: A2\n-->\n# A2');
  ws.terminate();
  await dev.stop();
  fs.rmSync(content, { recursive: true, force: true });
  fs.rmSync(output, { recursive: true, force: true });
  fs.rmSync(templates, { recursive: true, force: true });
  console.log('done');
  listHandles();
  setTimeout(() => { listHandles(); process.exit(0); }, 500);
}
main();
