const path = require('path');
const { createDevServer } = require('./dist/src/serve.js');

function listHandles(tag) {
  const handles = process._getActiveHandles();
  console.log(tag, 'handles:', handles.length);
  for (const h of handles) {
    const name = h.constructor ? h.constructor.name : '?';
    let extra = '';
    if (name === 'Socket') extra = ' destroyed=' + h.destroyed + ' ' + (h.remoteAddress||'') ;
    else if (name === 'Timer') extra = ' repeat=' + (h._repeat||'') ;
    console.log(' ', name, extra);
  }
}

async function run(label, withGet, withWs) {
  const content = fs.mkdtempSync(path.join(os.tmpdir(), 'r-'));
  const output = fs.mkdtempSync(path.join(os.tmpdir(), 'r-'));
  const templates = fs.mkdtempSync(path.join(os.tmpdir(), 'r-'));
  fs.writeFileSync(path.join(content, 'a.md'), '<!--\ntitle: A\n-->\n# A');
  const dev = createDevServer({ content, output, templates, port: 0 });
  const port = await dev.listen();
  await dev.ready;
  let ws;
  if (withGet) {
    await new Promise((res, rej) => http.get(`http://127.0.0.1:${port}/a.html`, { agent: false }, (r) => {
      r.resume(); r.on('end', res);
    }).on('error', rej));
  }
  if (withWs) {
    ws = new WebSocket(`ws://127.0.0.1:${port}${WS_PATH}`);
    await new Promise((res, rej) => { ws.once('open', res); ws.once('error', rej); });
    ws.terminate();
  }
  await dev.stop();
  fs.rmSync(content, { recursive: true, force: true });
  fs.rmSync(output, { recursive: true, force: true });
  fs.rmSync(templates, { recursive: true, force: true });
  listHandles(label + ' AFTER STOP');
}
const http = require('http');
const { WebSocket } = require('ws');
const { WS_PATH } = require('./dist/src/serve.js');
run('plain', false, false).then(() => run('withGet', true, false)).then(() => run('withWs', false, true)).then(() => setTimeout(() => process.exit(0), 100));
EOF
