const fs = require('fs');
const os = require('os');
const path = require('path');
const http = require('http');
const chokidar = require('chokidar');

function dump(tag) {
  const h = process._getActiveHandles().map((x) => (x.constructor.name) + (x.constructor.name==='Socket' ? '(destroyed='+x.destroyed+')' : '')).join(',');
  const t = process._getActiveRequests().length;
  console.log(`[${tag}] handles=${h} requests=${t}`);
}

async function main() {
  const content = fs.mkdtempSync(path.join(os.tmpdir(), 'r-'));
  const watcher = chokidar.watch(content, { ignoreInitial: true });
  const server = http.createServer((_req, res) => {
    res.writeHead(200, { 'Content-Type': 'text/html' });
    res.end('<html></html>');
  });
  await new Promise((r) => server.listen(0, () => r()));
  const port = server.address().port;
  await new Promise((res, rej) => http.get(`http://127.0.0.1:${port}/`, { agent: false }, (r) => {
    r.resume(); r.on('end', res);
  }).on('error', rej));
  await watcher.close();
  await new Promise((resolve) => server.close(() => resolve()));
  dump('after close');
  await new Promise((r) => setTimeout(r, 300));
  dump('after 300ms');
  fs.rmSync(content, { recursive: true, force: true });
}
main();
EOF
