import fs from 'fs';
import os from 'os';
import path from 'path';
import http from 'http';
import chokidar from 'chokidar';

test('aggressive socket cleanup', async () => {
  const content = fs.mkdtempSync(path.join(os.tmpdir(), 'min-'));
  const watcher = chokidar.watch(content, { ignoreInitial: true });
  const server = http.createServer((_req, res) => {
    res.writeHead(200, { 'Content-Type': 'text/html', 'Connection': 'close' });
    res.end('<html></html>');
  });
  server.keepAliveTimeout = 1;
  await new Promise<void>((r) => server.listen(0, () => r()));
  const port = (server.address() as { port: number }).port;
  await new Promise<void>((resolve, reject) => {
    const req = http.get(`http://127.0.0.1:${port}/`, { agent: false }, (res) => {
      res.resume();
      res.on('end', () => {
        (res as any).socket?.destroy();
        resolve();
      });
    });
    req.on('error', reject);
  });
  await watcher.close();
  await new Promise<void>((resolve) => {
    server.close(() => resolve());
    server.closeAllConnections();
  });
  fs.rmSync(content, { recursive: true, force: true });
});
EOF
