import fs from 'fs';
import os from 'os';
import path from 'path';
import http from 'http';
import chokidar from 'chokidar';

const proc: any = process;
function dump(tag: string) {
  const h = proc._getActiveHandles().map((x: any) => {
    if (x.constructor?.name === 'Socket') {
      return `Socket(local=${x.localPort} remote=${x.remotePort} destroyed=${x.destroyed})`;
    }
    return x.constructor?.name;
  }).join(',');
  const t = proc._getActiveRequests()?.length ?? 0;
  process.stderr.write(`[${tag}] handles=${h} requests=${t}\n`);
}

test('identify lingering', async () => {
  const content = fs.mkdtempSync(path.join(os.tmpdir(), 'min-'));
  const watcher = chokidar.watch(content, { ignoreInitial: true });
  const server = http.createServer((_req, res) => {
    res.writeHead(200, { 'Content-Type': 'text/html' });
    res.end('<html></html>');
  });
  await new Promise<void>((r) => server.listen(0, () => r()));
  const port = (server.address() as { port: number }).port;
  await new Promise<void>((resolve, reject) => {
    http.get(`http://127.0.0.1:${port}/`, { agent: false }, (res) => {
      res.resume();
      res.on('end', () => resolve());
    }).on('error', reject);
  });
  dump('after get resolved');
  await watcher.close();
  await new Promise<void>((resolve) => server.close(() => resolve()));
  dump('after closes');
  await new Promise<void>((r) => setTimeout(r, 500));
  dump('after 500ms');
  fs.rmSync(content, { recursive: true, force: true });
});
EOF
